<script src="{{ asset('backend/chart.js/chart.umd.min.js') }}"></script>
<script>
document.addEventListener('DOMContentLoaded', function () {
    const form=document.getElementById('dashboardFilters');
    document.getElementById('dashboardPeriod').addEventListener('change',function(){form.elements.from.value='';form.elements.to.value='';form.submit();});
    if(!window.Chart){document.querySelectorAll('.chart-box').forEach(box=>{box.textContent=@json(__('Charts could not load. Overview figures and tables remain available.'));});return;}
    const cards=@json($providerCards),health=@json($health),labels=@json($chartLabels),charts={};
    const palette=['#3269b2','#208768','#7254b5','#c17625','#8897aa'];
    const emptyPlugin={id:'emptyState',afterDraw(chart){if(chart.data.datasets.every(set=>set.data.every(value=>Number(value)===0))){const {ctx,chartArea}=chart;if(!chartArea)return;ctx.save();ctx.fillStyle='#718096';ctx.font='14px sans-serif';ctx.textAlign='center';ctx.fillText(@json(__('No data for this selection')),(chartArea.left+chartArea.right)/2,(chartArea.top+chartArea.bottom)/2);ctx.restore();}}};
    function create(id,type,data,extra={}){const canvas=document.getElementById(id);if(!canvas)return;charts[id]=new Chart(canvas,{type,data,plugins:[emptyPlugin],options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:8,padding:16}}},...(type==='doughnut'?{cutout:'68%'}:{scales:{x:{grid:{display:false}},y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#edf1f6'}}}}),...extra}});}
    create('revenueChart','line',{labels,datasets:@json($revenue)},{plugins:{legend:{position:'bottom',labels:{usePointStyle:true}},tooltip:{callbacks:{label:context=>context.dataset.label+': KES '+Number(context.parsed.y).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}}}});
    create('growthChart','line',{labels,datasets:@json($growth)});
    create('providerChart','doughnut',{labels:cards.map(row=>row.label),datasets:[{data:cards.map(row=>row.count),backgroundColor:cards.map(row=>row.color),borderWidth:3,borderColor:'#fff'}]},{interaction:{mode:'nearest',intersect:true},onClick(event,elements){if(elements.length)window.location.href=cards[elements[0].index].url;},onHover(event,elements){event.native.target.style.cursor=elements.length?'pointer':'default';}});
    create('healthChart','bar',{labels:health.map(row=>row.label),datasets:[{label:@json(__('Active accounts')),data:health.map(row=>row.active),backgroundColor:'#208768',borderRadius:4},{label:@json(__('Pending plans')),data:health.map(row=>row.pending),backgroundColor:'#e4a33a',borderRadius:4},{label:@json(__('Expired plans')),data:health.map(row=>row.expired),backgroundColor:'#de6570',borderRadius:4}]});
    @if($canCreators)
    const sources=@json($sources),sourceNames={admin:@json(__('Admin')),employee:@json(__('Employee')),self:@json(__('Self-registration')),system:@json(__('System')),unknown:@json(__('Unknown'))},staff=@json($staff);
    create('sourceChart','doughnut',{labels:Object.keys(sources).map(key=>sourceNames[key]||key),datasets:[{data:Object.values(sources),backgroundColor:palette,borderWidth:3,borderColor:'#fff'}]});
    const staffDatasets=[{label:@json(__('Accounts created')),data:staff.map(row=>row.created),backgroundColor:'#3269b2',borderRadius:4}];
    @if($canFinance)staffDatasets.push({label:@json(__('Payments confirmed')),data:staff.map(row=>row.confirmed),backgroundColor:'#208768',borderRadius:4});@endif
    create('staffChart','bar',{labels:staff.map(row=>row.name),datasets:staffDatasets},{indexAxis:'y',scales:{x:{beginAtZero:true,ticks:{precision:0},grid:{color:'#edf1f6'}},y:{grid:{display:false}}}});
    @endif
    document.querySelectorAll('[data-chart-toggle]').forEach(button=>button.addEventListener('click',()=>{const chart=charts[button.dataset.chartToggle];if(!chart)return;chart.config.type=chart.config.type==='line'?'bar':'line';chart.update();}));
});
</script>
@endpush